INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('275c740d-e9b2-456f-84d3-7e2d2e764762', 'b2b2b2b2-3030-4000-8000-000000000002', 29, 'Dia 29 — Testemunho', 'Semana 4: Integrar', '{"pch": "Tirou-me do po\u00e7o\u2026 e p\u00f4s nos meus l\u00e1bios um c\u00e2ntico novo. Sua hist\u00f3ria \u00e9 seu testemunho.", "verse": "Sl 40,2-3", "lectio": "Leia Sl 40,1-5. Da espera ao louvor.", "practice": "Escreva seu testemunho em 5 frases.", "question": "O que voc\u00ea diria a algu\u00e9m que est\u00e1 onde voc\u00ea estava?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;